# ---------------------------------------------------------------------------
# DB session helper
# ---------------------------------------------------------------------------

@asynccontextmanager
async def _db_session() -> AsyncGenerator[AsyncSession, None]:
    """
    Yield an AsyncSession for use inside a node.

    Usage:
        async with _db_session() as db:
            result = await db.execute(select(Task).where(...))
            ...
            await db.commit()

    Always commits on clean exit, always rolls back on exception.
    Never hold this open across multiple node invocations.
    """
    async with AsyncSessionLocal() as session:
        try:
            yield session
            await session.commit()
        except Exception:
            await session.rollback()
            raise


