async def load_context(state: OrchestratorState) -> OrchestratorState:
    """
    Graph entry node.  Loads everything the orchestrator needs into state:

    1. Fetch the Run record for architecture_run_id â€” confirm it exists
       and is in COMPLETED status.
    2. Load all Task rows for this codegen run_id, sorted by order_index.
    3. Load requirements document text from the architecture run's artifacts.
    4. Load architecture spec text from the architecture run's artifacts.

    Fails fast with a clear error if:
    - The architecture run doesn't exist or isn't completed.
    - No tasks are found for this run.
    - Neither artifacts nor output_data contains the architecture spec.

    On failure, sets state["error"] â€” the router will send the run to FAIL.
    """
    run_id              = state["run_id"]
    project_id          = state["project_id"]
    architecture_run_id = state["architecture_run_id"]

    log.info(
        "load_context | run_id=%s | architecture_run_id=%s",
        run_id, architecture_run_id,
    )

    async with _db_session() as db:
        # -- Verify architecture run -----------------------------------------
        arch_run_result = await db.execute(
            select(Run).where(Run.id == architecture_run_id)
        )
        arch_run: Optional[Run] = arch_run_result.scalar_one_or_none()

        if not arch_run:
            return {**state, "error": f"Architecture run {architecture_run_id!r} not found."}

        arch_status = arch_run.status.value if hasattr(arch_run.status, "value") else str(arch_run.status)
        if arch_status != "completed":
            return {
                **state,
                "error": (
                    f"Architecture run {architecture_run_id!r} is not completed "
                    f"(status={arch_status!r}).  "
                    "Codegen requires an approved, completed architecture run."
                ),
            }

        # -- Load task list ---------------------------------------------------
        tasks_result = await db.execute(
            select(Task)
            .where(Task.run_id == run_id)
            .order_by(Task.order_index)
        )
        tasks: list[Task] = list(tasks_result.scalars().all())

        if not tasks:
            return {
                **state,
                "error": (
                    f"No tasks found for run_id={run_id!r}.  "
                    "The architecture workflow must have written tasks before "
                    "codegen can be triggered."
                ),
            }

        task_dicts = [TaskRecord.from_orm(t).to_dict() for t in tasks]

    # -- Load requirements context -------------------------------------------
    # Try artifacts file first; fall back to output_data["requirements"]
    requirements_context = await _load_text_artifact(
        project_id       = project_id,
        run_id           = architecture_run_id,
        filename         = "requirements.md",
        fallback_run     = arch_run,
        fallback_key     = "requirements",
    )

    # -- Load architecture context --------------------------------------------
    architecture_context = await _load_text_artifact(
        project_id       = project_id,
        run_id           = architecture_run_id,
        filename         = "architecture.json",
        fallback_run     = arch_run,
        fallback_key     = "architecture",
    )

    if not architecture_context:
        return {
            **state,
            "error": (
                f"Could not load architecture spec for run {architecture_run_id!r}.  "
                "Expected artifacts/architecture.json or output_data['architecture']."
            ),
        }

    log.info(
        "load_context | loaded %d tasks | "
        "requirements=%d chars | architecture=%d chars",
        len(task_dicts),
        len(requirements_context),
        len(architecture_context),
    )

    return {
        **state,
        "tasks":                task_dicts,
        "current_task_index":   0,
        "completed_task_ids":   [],
        "failed_task_ids":      [],
        "requirements_context": requirements_context,
        "architecture_context": architecture_context,
        "bundle_path":          None,
        "manifest":             None,
        "hitl_request_id":      None,
        "error":                None,
    }


async def _load_text_artifact(
    *,
    project_id:   str,
    run_id:       str,
    filename:     str,
    fallback_run: Run,
    fallback_key: str,
) -> str:
    """
    Try to read a text artifact from the filesystem; fall back to
    run.output_data[fallback_key] if the file doesn't exist.

    Returns an empty string if neither source has the content.
    """
    artifact_path = os.path.join(
        file_store.artifacts_dir(project_id, run_id), filename
    )

    if file_store.file_exists(artifact_path):
        try:
            return await file_store.read_file(artifact_path)
        except Exception as exc:
            log.warning("Could not read artifact %s: %s", artifact_path, exc)

    # Fallback: output_data on the Run record
    if fallback_run.output_data and fallback_key in fallback_run.output_data:
        value = fallback_run.output_data[fallback_key]
        # May be a dict (JSON) or a string
        if isinstance(value, dict):
            return json.dumps(value, indent=2)
        return str(value)

    return ""


