async def pick_next_task(state: OrchestratorState) -> OrchestratorState:
    """
    Mark the current task as in_progress in the DB and return updated state.

    This is a lightweight node â€” it advances the cursor and writes a
    single status field.  The heavy lifting (LLM calls, file I/O) happens
    inside the subgraph.
    """
    tasks = state["tasks"]
    idx   = state["current_task_index"]

    if idx >= len(tasks):
        # Shouldn't reach here â€” route_orchestrator guards this.
        # Defensive: set error so the router sends to FAIL.
        return {**state, "error": "current_task_index out of bounds in pick_next_task."}

    task = TaskRecord.from_dict(tasks[idx])

    log.info(
        "pick_next_task | run_id=%s | index=%d | task_id=%s | title=%r",
        state["run_id"], idx, task.id, task.title,
    )

    async with _db_session() as db:
        db_task = await db.get(Task, task.id)
        if db_task:
            db_task.status     = TaskStatus.IN_PROGRESS.value
            db_task.started_at = datetime.now(timezone.utc)

    # Reflect in-memory state so subgraph sees in_progress
    task.status = TaskStatus.IN_PROGRESS.value
    updated_tasks = list(tasks)
    updated_tasks[idx] = task.to_dict()

    return {**state, "tasks": updated_tasks}


