async def record_task_result(state: OrchestratorState) -> OrchestratorState:
    """
    Called by the orchestrator after each subgraph completes.

    Reads the subgraph's result from state["_last_task_result"] â€” a dict
    written by the subgraph's terminal node before returning.  Updates:

    - The Task row in DB (status, retry_count, generated_files, error)
    - The TaskRecord dict in state["tasks"][current_task_index]
    - state["completed_task_ids"] or state["failed_task_ids"]
    - Advances state["current_task_index"] by 1

    "_last_task_result" structure:
        {
          "task_id":        str,
          "final_status":   "completed" | "failed",
          "retry_count":    int,
          "generated_files": list[str],
          "feedback":       str | None,
          "error":          str | None,
        }
    """
    result = state.get("_last_task_result", {})
    idx    = state["current_task_index"]
    tasks  = list(state["tasks"])

    task_id      = result.get("task_id", "")
    final_status = result.get("final_status", TaskStatus.FAILED.value)
    retry_count  = result.get("retry_count", 0)
    gen_files    = result.get("generated_files", [])
    feedback     = result.get("feedback")
    error        = result.get("error")

    log.info(
        "record_task_result | task_id=%s | status=%s | files=%d",
        task_id, final_status, len(gen_files),
    )

    # -- Update DB ------------------------------------------------------------
    async with _db_session() as db:
        db_task = await db.get(Task, task_id)
        if db_task:
            db_task.status          = final_status
            db_task.retry_count     = retry_count
            db_task.generated_files = gen_files
            db_task.feedback        = feedback
            db_task.error           = error
            db_task.finished_at     = datetime.now(timezone.utc)

    # -- Update in-memory task record ----------------------------------------
    if 0 <= idx < len(tasks):
        task = TaskRecord.from_dict(tasks[idx])
        task.status          = final_status
        task.retry_count     = retry_count
        task.generated_files = gen_files
        task.feedback        = feedback
        task.error           = error
        tasks[idx] = task.to_dict()

    # -- Update progress lists -----------------------------------------------
    completed_ids = list(state.get("completed_task_ids", []))
    failed_ids = list(state.get("failed_task_ids", []))
    if final_status == TaskStatus.COMPLETED.value:
        if task_id not in completed_ids:
            completed_ids.append(task_id)
        failed_ids = [existing for existing in failed_ids if existing != task_id]
    else:
        if task_id not in failed_ids:
            failed_ids.append(task_id)
        completed_ids = [existing for existing in completed_ids if existing != task_id]
    return {
        **state,
        "tasks":               tasks,
        "current_task_index":  idx + 1,
        "completed_task_ids":  completed_ids,  # reducer appends
        "failed_task_ids":     failed_ids,     # reducer appends
        "_last_task_result":   None,
    }


