async def bundle_workspace(state: OrchestratorState) -> OrchestratorState:
    """
    Zip the workspace and write MANIFEST.json.

    MANIFEST.json structure:
        {
          "run_id":      str,
          "project_id":  str,
          "generated_at": ISO timestamp,
          "tasks": {
            "<task_id>": {
              "title":  str,
              "status": str,
              "files":  ["relative/path/a.py", ...]
            },
            ...
          },
          "all_files": ["sorted", "list", "of", "all", "paths"]
        }
    """
    run_id     = state["run_id"]
    project_id = state["project_id"]

    log.info("bundle_workspace | run_id=%s | project_id=%s", run_id, project_id)

    # -- Build manifest -------------------------------------------------------
    tasks      = state.get("tasks", [])
    task_index = {}
    for t_dict in tasks:
        task = TaskRecord.from_dict(t_dict)
        task_index[task.id] = {
            "title":  task.title,
            "status": task.status,
            "files":  task.generated_files,
        }

    all_files = sorted(set(file_store.list_workspace_files(project_id, run_id) + ["MANIFEST.json"]))

    manifest = {
        "run_id":        run_id,
        "project_id":    project_id,
        "generated_at":  datetime.now(timezone.utc).isoformat(),
        "tasks":         task_index,
        "all_files":     all_files,
        "completed_tasks": state.get("completed_task_ids", []),
        "failed_tasks":    state.get("failed_task_ids", []),
        "final_approval": {
            "status": "pending",
            "approved": None,
            "decision": None,
            "feedback": None,
            "request_id": None,
            "decided_at": None,
        },
    }

    manifest_json = json.dumps(manifest, indent=2)

    # -- Write MANIFEST.json to workspace (included in bundle) and artifacts --
    await file_store.save_workspace_file(
        project_id    = project_id,
        run_id        = run_id,
        relative_path = "MANIFEST.json",
        content       = manifest_json,
    )
    await file_store.save_artifact(
        project_id = project_id,
        run_id     = run_id,
        filename   = "MANIFEST.json",
        content    = manifest_json,
    )

    # -- Create bundle.zip ----------------------------------------------------
    try:
        bundle_path = file_store.create_bundle(project_id, run_id)
        log.info("bundle_workspace | bundle created at %s", bundle_path)
    except Exception as exc:
        log.error("bundle_workspace | failed to create bundle: %s", exc)
        return {**state, "error": f"Bundle creation failed: {exc}"}

    # -- Persist bundle path on Run record ------------------------------------
    async with _db_session() as db:
        db_run = await db.get(Run, run_id)
        if db_run:
            meta = db_run.run_metadata or {}
            meta["bundle_path"] = bundle_path
            meta["manifest"]    = manifest
            db_run.run_metadata = meta

    return {
        **state,
        "bundle_path": bundle_path,
        "manifest":    manifest,
    }


