async def request_approval(state: OrchestratorState) -> OrchestratorState:
    """
    Create an approval request, publish it, and pause with LangGraph interrupt().

    On first execution, interrupt() stores the checkpoint and returns control to
    the caller. On resume, Command(resume=...) returns the human decision here
    and this node records the final approval state before the graph reaches END.
    """
    run_id = state["run_id"]
    project_id = state["project_id"]
    request_id = state.get("hitl_request_id")
    if not request_id:
        async with _db_session() as db:
            existing_run = await db.get(Run, run_id)
            if existing_run and existing_run.pending_hitl_request_id:
                request_id = existing_run.pending_hitl_request_id
    request_id = request_id or str(uuid.uuid4())

    log.info("request_approval | run_id=%s | request_id=%s", run_id, request_id)

    manifest = dict(state.get("manifest") or {})
    final_approval = dict(manifest.get("final_approval") or {})
    final_approval.update({
        "status": "pending",
        "approved": None,
        "decision": None,
        "feedback": None,
        "request_id": request_id,
        "requested_at": datetime.now(timezone.utc).isoformat(),
        "decided_at": None,
    })
    manifest["final_approval"] = final_approval
    manifest["hitl_request_id"] = request_id

    bundle_path = state.get("bundle_path")
    try:
        manifest_json = json.dumps(manifest, indent=2)
        await file_store.save_workspace_file(
            project_id=project_id,
            run_id=run_id,
            relative_path="MANIFEST.json",
            content=manifest_json,
        )
        await file_store.save_artifact(
            project_id=project_id,
            run_id=run_id,
            filename="MANIFEST.json",
            content=manifest_json,
        )
        bundle_path = file_store.create_bundle(project_id, run_id)
    except Exception as exc:
        log.warning("request_approval | manifest approval stamp failed: %s", exc)

    state = {**state, "manifest": manifest, "bundle_path": bundle_path}

    payload = {
        "type": "approval_request",
        "request_id": request_id,
        "run_id": run_id,
        "project_id": project_id,
        "bundle_path": bundle_path,
        "summary": {
            "completed_tasks": len(state.get("completed_task_ids", [])),
            "failed_tasks": len(state.get("failed_task_ids", [])),
            "total_tasks": len(state.get("tasks", [])),
            "all_files": state.get("manifest", {}).get("all_files", []),
        },
        "message": "Codegen complete. Please review the bundle and approve or reject.",
    }

    output_data = {
        "completed_task_ids": state.get("completed_task_ids", []),
        "failed_task_ids": state.get("failed_task_ids", []),
        "bundle_path": state.get("bundle_path"),
        "manifest": state.get("manifest"),
        "hitl_request_id": request_id,
        "error": state.get("error"),
    }

    async with _db_session() as db:
        existing = await db.get(Approval, request_id)
        if not existing:
            db.add(
                Approval(
                    id=request_id,
                    project_id=project_id,
                    run_id=run_id,
                    workflow_type="codegen",
                    request_id=request_id,
                    status="pending",
                    artifact_urls=[bundle_path] if bundle_path else [],
                    payload=payload,
                )
            )

        db_run = await db.get(Run, run_id)
        if db_run:
            db_run.status = "paused_hitl"
            db_run.pending_hitl_request_id = request_id
            db_run.pending_hitl_type = "approval"
            db_run.output_data = output_data

    await emit_event(
        "approval_requested",
        payload,
        run_id=run_id,
        project_id=project_id,
        node_name="request_approval",
        message="Waiting for human approval",
    )

    try:
        from app.hitl.manager import push_to_run
        await push_to_run(run_id, "approval_request", payload)
    except Exception as exc:
        log.warning("request_approval | HITL push failed: %s", exc)

    decision_payload = interrupt(payload) or {}
    approved = bool(
        decision_payload.get("approved")
        if "approved" in decision_payload
        else decision_payload.get("decision") == "approve"
    )
    feedback = decision_payload.get("feedback")

    async with _db_session() as db:
        approval = await db.get(Approval, request_id)
        if approval:
            approval.status = "approved" if approved else "rejected"
            approval.decision = "approve" if approved else "reject"
            approval.approved = approved
            approval.feedback = feedback
            approval.decided_at = datetime.now(timezone.utc)
            approval.resolved_at = approval.decided_at
            approval.payload = {**(approval.payload or payload), "response": decision_payload}

    await emit_event(
        "approval_resumed",
        {"request_id": request_id, "approved": approved, "feedback": feedback},
        run_id=run_id,
        project_id=project_id,
        node_name="request_approval",
        message="Human approval received",
    )

    return {
        **state,
        "hitl_request_id": None,
        "approval_decision": "approve" if approved else "reject",
        "approval_feedback": feedback,
        "error": None if approved else (feedback or "Rejected by reviewer."),
    }

