async def developer_node(state: TaskState) -> TaskState:
    """
    Core developer agent.  Calls OpenAI with a pattern-aware prompt and
    parses the response into a list of staged GeneratedFile dicts.

    On first attempt (retry_count == 0 and no critic_feedback):
        Uses build_developer_prompt()

    On retry (retry_count > 0):
        Uses build_retry_prompt() â€” includes previous output + reviewer feedback

    On Reflection iteration (critic_feedback is set):
        Uses build_developer_prompt() with critic_feedback injected â€”
        the developer knows it's revising in response to the critic,
        not the human reviewers.

    Sets state["developer_output"] and state["pending_files"].
    Sets state["error"] on parse failure (no <file> blocks found).
    """
    task        = TaskRecord.from_dict(state["task"])
    retry_count = state.get("retry_count", 0)
    agg_feedback = state.get("aggregated_feedback")
    critic_feedback = state.get("critic_feedback")

    existing_files = file_store.list_workspace_files(
        state["project_id"], state["run_id"]
    )

    log.info(
        "developer_node | task_id=%s | retry=%d | "
        "has_feedback=%s | has_critic=%s",
        task.id, retry_count,
        bool(agg_feedback), bool(critic_feedback),
    )

    # -- Choose prompt strategy ----------------------------------------------
    if retry_count > 0 and agg_feedback:
        messages = build_retry_prompt(
            task_title            = task.title,
            task_description      = task.description,
            pattern_refs          = task.pattern_refs,
            requirements_context  = state.get("requirements_context", ""),
            architecture_context  = state.get("architecture_context", ""),
            developer_output      = state.get("developer_output", ""),
            aggregated_feedback   = agg_feedback,
            retry_number          = retry_count,
            max_retries           = state.get("max_retries", 3),
            existing_files        = existing_files,
        )
    else:
        messages = build_developer_prompt(
            task_title            = task.title,
            task_description      = task.description,
            pattern_refs          = task.pattern_refs,
            requirements_context  = state.get("requirements_context", ""),
            architecture_context  = state.get("architecture_context", ""),
            existing_files        = existing_files,
            critic_feedback       = critic_feedback,
        )

    # -- Call OpenAI ----------------------------------------------------------
    try:
        raw_output = await _chat(
            messages   = messages,
            model      = _DEVELOPER_MODEL,
            max_tokens = _DEVELOPER_MAX_TOKENS,
            temperature = 0.2,
            node_name = "developer_node",
            run_id = state.get("run_id"),
            project_id = state.get("project_id"),
        )
    except Exception as exc:
        log.error("developer_node | OpenAI call failed: %s", exc)
        return {
            **state,
            "developer_output": "",
            "pending_files":    [],
            "error":            f"LLM call failed: {exc}",
        }

    # -- Parse output ---------------------------------------------------------
    try:
        parsed_files = parse_developer_output(raw_output)
    except ValueError as exc:
        log.warning("developer_node | parse failed: %s", exc)
        return {
            **state,
            "developer_output": raw_output,
            "pending_files":    [],
            "error":            str(exc),
        }

    pending = [
        GeneratedFile(
            relative_path = pf.relative_path,
            content       = pf.content,
            task_id       = task.id,
        ).to_dict()
        for pf in parsed_files
    ]

    log.info(
        "developer_node | task_id=%s | parsed %d file(s): %s",
        task.id,
        len(pending),
        [p["relative_path"] for p in pending],
    )

    return {
        **state,
        "developer_output": raw_output,
        "pending_files":    pending,
        "critic_feedback":  None,   # clear from previous iteration
        "error":            None,
    }



