def _has_tool_function_docstring(pending: list[dict]) -> bool:
    """Return True when any generated Python function has a docstring."""
    fallback = re.compile(
        r"def\s+\w+\s*\([^)]*\)\s*:[ \t]*(?:\r?\n)[ \t]*(?:[rRuUfF]*)(?:'''|\"\"\")"
    )
    for item in pending:
        content = str(item.get("content", ""))
        try:
            tree = ast.parse(content)
        except SyntaxError:
            if fallback.search(content):
                return True
            continue
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and ast.get_docstring(node):
                return True
    return False


# ---------------------------------------------------------------------------

async def tool_syntax_check_node(state: TaskState) -> TaskState:
    """
    Static Tool-Use guardrail before LLM reviewers.

    A Tool-Use task must stage at least one file that defines callable tools,
    registers them in a tools list, and constructs a LangGraph ToolNode. This
    catches common malformed generations before spending reviewer calls.
    """
    task = TaskRecord.from_dict(state["task"])
    pending = state.get("pending_files", [])
    retry_count = state.get("retry_count", 0)

    combined = "\n\n".join(str(item.get("content", "")) for item in pending)
    issues: list[str] = []

    if not pending:
        issues.append("No generated files were staged for Tool-Use validation.")
    if "ToolNode" not in combined:
        issues.append("Generated code must import or instantiate langgraph.prebuilt.ToolNode.")
    if not re.search(r"\btools\s*=\s*\[", combined):
        issues.append("Generated code must define a tools = [...] registry.")
    if not _has_tool_function_docstring(pending):
        issues.append("At least one tool function must include a docstring.")

    if not issues:
        log.info("tool_syntax_check_node | task_id=%s | passed", task.id)
        return {
            **state,
            "aggregated_feedback": None,
            "error": None,
        }

    feedback = "Tool-Use validation failed:\n" + "\n".join(f"- {issue}" for issue in issues)
    log.info(
        "tool_syntax_check_node | task_id=%s | failed | retry=%d | issues=%s",
        task.id,
        retry_count,
        issues,
    )
    return {
        **state,
        "review_passed": False,
        "aggregated_feedback": feedback,
        "retry_count": retry_count + 1,
        "error": None,
    }

async def critic_node(state: TaskState) -> TaskState:
    """
    Reflection-pattern inner critic.

    Evaluates the developer's output for completeness, pattern compliance,
    and obvious logic errors before it reaches the human reviewers.

    Returns:
    - If passed=True:  clears critic_feedback â†’ route_after_critic sends
      to reviewers.
    - If passed=False: sets critic_feedback â†’ route_after_critic sends
      back to developer_node for revision.

    Critic parse failure is soft â€” if the LLM returns malformed JSON,
    we pass through to reviewers rather than blocking the pipeline.
    """
    task = TaskRecord.from_dict(state["task"])

    log.info("critic_node | task_id=%s", task.id)

    messages = build_critic_prompt(
        task_title       = task.title,
        task_description = task.description,
        pattern_refs     = task.pattern_refs,
        developer_output = state.get("developer_output", ""),
    )

    try:
        raw_output = await _chat(
            messages    = messages,
            model       = _REVIEWER_MODEL,
            max_tokens  = _CRITIC_MAX_TOKENS,
            temperature = 0.0,
            node_name = "critic_node",
            run_id = state.get("run_id"),
            project_id = state.get("project_id"),
        )
    except Exception as exc:
        log.error("critic_node | OpenAI call failed: %s â€” passing through", exc)
        return {**state, "critic_feedback": None}

    passed, feedback = parse_critic_output(raw_output)

    log.info(
        "critic_node | task_id=%s | passed=%s | feedback_len=%d",
        task.id, passed, len(feedback),
    )

    if passed:
        return {
            **state,
            "critic_feedback": None,
            "aggregated_feedback": None,
            "error": None,
        }

    return {
        **state,
        "critic_feedback": feedback,
        "aggregated_feedback": feedback,
        "retry_count": state.get("retry_count", 0) + 1,
        "review_passed": False,
        "error": None,
    }


# ---------------------------------------------------------------------------
# Reviewer nodes â€” run in parallel via LangGraph fan-out
# Each appends exactly one ReviewerVerdict dict to reviewer_verdicts.
# The operator.add reducer in TaskState ensures no race condition.
# ---------------------------------------------------------------------------

async def workflow_reviewer_node(state: TaskState) -> TaskState:
    """
    Reviewer 1: workflow correctness and pattern alignment.
    Appends one ReviewerVerdict dict to state["reviewer_verdicts"].
    """
    task       = TaskRecord.from_dict(state["task"])
    reviewer   = "workflow_reviewer"

    log.info("workflow_reviewer_node | task_id=%s", task.id)

    messages = build_workflow_reviewer_prompt(
        task_title            = task.title,
        task_description      = task.description,
        pattern_refs          = task.pattern_refs,
        developer_output      = state.get("developer_output", ""),
        architecture_context  = state.get("architecture_context", ""),
    )

    verdict = await _call_reviewer(
        reviewer=reviewer,
        messages=messages,
        run_id=state.get("run_id"),
        project_id=state.get("project_id"),
        attempt=state.get("retry_count", 0),
    )

    log.info(
        "workflow_reviewer_node | task_id=%s | passed=%s",
        task.id, verdict.passed,
    )

    return {"reviewer_verdicts": [verdict.to_dict()]}


