async def _call_reviewer(
    *,
    reviewer: str,
    messages: list[dict],
    run_id: str | None = None,
    project_id: str | None = None,
    attempt: int = 0,
) -> ReviewerVerdict:
    """
    Shared helper: call OpenAI for any reviewer node and parse the verdict.

    Returns a blocking-failure ReviewerVerdict if the LLM call itself
    fails â€” we never silently pass on a reviewer error.
    """
    try:
        raw = await _chat(
            messages    = messages,
            model       = _REVIEWER_MODEL,
            max_tokens  = _REVIEWER_MAX_TOKENS,
            temperature = 0.0,
            node_name = f"{reviewer}_node",
            run_id = run_id,
            project_id = project_id,
        )
    except Exception as exc:
        log.error("_call_reviewer | %s | LLM call failed: %s", reviewer, exc)
        return ReviewerVerdict(
            reviewer = reviewer,
            passed   = False,
            feedback = f"{reviewer} LLM call failed: {exc}",
            severity = "blocking",
            attempt  = attempt,
        )

    parsed = parse_reviewer_verdict(raw, reviewer)

    return ReviewerVerdict(
        reviewer = reviewer,
        passed   = parsed.passed,
        feedback = parsed.feedback,
        severity = parsed.severity,
        attempt  = attempt,
    )


# ---------------------------------------------------------------------------

async def reduce_verdicts_node(state: TaskState) -> TaskState:
    """
    Collapse the three parallel reviewer verdicts into a single pass/fail.

    Logic:
    - A blocking failure from ANY reviewer â†’ review_passed=False.
    - Advisory failures are logged but do not affect pass/fail.
    - If review_passed=False, aggregated_feedback concatenates all
      blocking feedback strings, labelled by reviewer name.
    - reviewer_verdicts is cleared after reduction so the list doesn't
      grow across retry iterations (the reducer would keep appending).

    Also increments retry_count so developer_node knows which iteration
    it's on if the route sends back for a retry.
    """
    verdicts_raw: list[dict] = state.get("reviewer_verdicts", [])
    retry_count:  int        = state.get("retry_count", 0)

    all_verdicts = [ReviewerVerdict.from_dict(v) for v in verdicts_raw]
    verdicts = [v for v in all_verdicts if v.attempt == retry_count]
    if not verdicts and all_verdicts:
        verdicts = all_verdicts

    blocking_failures = [
        v for v in verdicts
        if not v.passed and v.severity == "blocking"
    ]
    advisory_failures = [
        v for v in verdicts
        if not v.passed and v.severity == "advisory"
    ]

    if advisory_failures:
        for v in advisory_failures:
            log.info(
                "reduce_verdicts | advisory: [%s] %s",
                v.reviewer, v.feedback,
            )

    if blocking_failures:
        feedback_parts = []
        for v in blocking_failures:
            feedback_parts.append(
                f"### {v.reviewer.replace('_', ' ').title()}\n{v.feedback.strip()}"
            )
        aggregated = "\n\n".join(feedback_parts)

        log.info(
            "reduce_verdicts | FAILED | retry=%d | blocking_reviewers=%s",
            retry_count,
            [v.reviewer for v in blocking_failures],
        )

        return {
            **state,
            "review_passed":       False,
            "aggregated_feedback": aggregated,
            "retry_count":         retry_count + 1,
        }

    log.info("reduce_verdicts | PASSED | retry=%d", retry_count)

    return {
        **state,
        "review_passed":       True,
        "aggregated_feedback": None,
    }


# ---------------------------------------------------------------------------

async def finalize_task_node(state: TaskState) -> TaskState:
    """
    Terminal node of the task subgraph.

    On review_passed=True:
      - Write all pending_files to disk via FileStore.save_workspace_file()
      - Set final_status="completed"

    On review_passed=False (retry cap exhausted):
      - Do NOT write any files to disk
      - Set final_status="failed"

    In both cases, writes "_last_task_result" into state so the
    orchestrator's record_task_result node can update the DB without
    needing to re-inspect subgraph state directly.

    File write failures are caught individually â€” if one file fails,
    the others are still written and the task is marked completed with
    a warning, not failed.  A complete write failure marks the task failed.
    """
    task          = TaskRecord.from_dict(state["task"])
    review_passed = state.get("review_passed", False)
    pending       = state.get("pending_files", [])
    retry_count   = state.get("retry_count", 0)
    run_id        = state["run_id"]
    project_id    = state["project_id"]

    log.info(
        "finalize_task_node | task_id=%s | review_passed=%s | files=%d",
        task.id, review_passed, len(pending),
    )

    generated_files: list[str] = []
    write_error: Optional[str] = None

    if review_passed and pending:
        for file_dict in pending:
            gf = GeneratedFile.from_dict(file_dict)
            try:
                await file_store.save_workspace_file(
                    project_id    = project_id,
                    run_id        = run_id,
                    relative_path = gf.relative_path,
                    content       = gf.content,
                )
                generated_files.append(gf.relative_path)
                log.info(
                    "finalize_task_node | wrote %s", gf.relative_path
                )
            except Exception as exc:
                log.error(
                    "finalize_task_node | failed to write %s: %s",
                    gf.relative_path, exc,
                )
                write_error = str(exc)

        if not generated_files:
            # Every file write failed
            final_status = TaskStatus.FAILED.value
            error        = write_error or "All file writes failed."
        else:
            final_status = TaskStatus.COMPLETED.value
            error        = write_error  # partial write warning, non-None but not fatal
    else:
        # review_passed=False with retry cap hit, or no files to write
        final_status = TaskStatus.FAILED.value
        error = state.get("aggregated_feedback") or state.get("error")

    last_result = {
        "task_id":         task.id,
        "final_status":    final_status,
        "retry_count":     retry_count,
        "generated_files": generated_files,
        "feedback":        state.get("aggregated_feedback"),
        "error":           error,
    }

    log.info(
        "finalize_task_node | task_id=%s | final_status=%s | files_written=%d",
        task.id, final_status, len(generated_files),
    )

    return {
        **state,
        "final_status":       final_status,
        "generated_files":    generated_files,
        "_last_task_result":  last_result,
    }


# ---------------------------------------------------------------------------
# ROUTING FUNCTIONS
# ---------------------------------------------------------------------------

def route_orchestrator(state: OrchestratorState) -> str:
    """
    Conditional edge from pick_next_task / record_task_result.

    FAIL          â†’ unrecoverable error set during load_context or bundling
    EXECUTE_TASK  â†’ more tasks remain in the list
    BUNDLE        â†’ all tasks processed, proceed to bundle + approval
    """
    if state.get("error"):
        return OrchestratorRoute.FAIL

    idx   = state.get("current_task_index", 0)
    tasks = state.get("tasks", [])

    if idx < len(tasks):
        return OrchestratorRoute.EXECUTE_TASK

    return OrchestratorRoute.BUNDLE


def route_after_critic(state: TaskState) -> str:
    """
    Conditional edge from critic_node.

    critic_feedback is None  â†’ critic passed â†’ proceed to reviewers (fan-out)
    critic_feedback is set   â†’ critic failed â†’ back to developer for revision
    """
    if state.get("critic_feedback"):
        return TaskRoute.TO_REVIEWERS   # actually goes back to developer
        # Note: the subgraph wires this edge to developer_node, not reviewers.
        # The constant name is TO_REVIEWERS as a default; subgraph.py overrides
        # the routing target for Reflection tasks.  See subgraph.py for wiring.
    return TaskRoute.TO_REVIEWERS


def route_after_reduce(state: TaskState) -> str:
    """
    Conditional edge from reduce_verdicts_node.

    FINALIZE â†’ review passed â†’ write files, complete task
    RETRY    â†’ review failed, retries remain â†’ back to developer
    FAIL     â†’ review failed, retry cap hit â†’ finalize as failed
    """
    review_passed = state.get("review_passed", False)
    retry_count   = state.get("retry_count", 0)
    max_retries   = state.get("max_retries", 3)

    if review_passed:
        return TaskRoute.FINALIZE

    if retry_count <= max_retries:
        return TaskRoute.RETRY

    return TaskRoute.FAIL







